module.exports = "';\nconst _STATS_B64 = '';\nconst _TERRENOS_B64 = '';\nconst _KPIS_B64 = 'eyJ0b3RhbCI6Mjc3NTksInByaW9yaWRhZGVfYSI6MzQ2OSwic2NvcmVfbWVkaW8iOjQ2LjI0MjU1MTk2NTEyODQzLCJwYXNzb2lyZXMiOjQ2MTIsImNvbV90ZXJyZW5vX2dyYW5kZSI6MTE3ODcsInZhbG9yX3RvdGFsX2VzdGltYWRvIjo1MzgyNzYxNTAwLjB9';\nfunction _b64json(s){ return JSON.parse(decodeURIComponent(escape(atob(s)))); }\nconst LEADS = _b64json(_LEADS_B64);\nconst STATS = _b64json(_STATS_B64);\nconst TERRENOS = _b64json(_TERRENOS_B64);\nconst KPIS = _b64json(_KPIS_B64);\n\nconst COLS = ['adresse','commune','secteur','prioridade','score','tipo','superficie','pieces',\n              'dpe','passoire','ano','terreno','prixm2','valor','maisvalia','duree',\n              'argDpe','argTerreno','argPrudent','nbComp','echeanceDpe','gmaps','motivos','comparaveis','superficieDpe','fichaIdx','sourceSurface'];\nconst IDX = Object.fromEntries(COLS.map((c,i)=>[c,i]));\n\nconst TCOLS = ['parcela','commune','area','zonaPlu','zonaLibelle','poiAlerta','linkMapa'];\nconst TIDX = Object.fromEntries(TCOLS.map((c,i)=>[c,i]));\n\nconst fmtEUR = new Intl.NumberFormat('fr-FR',{style:'currency',currency:'EUR',maximumFractionDigits:0});\nconst fmtNum = new Intl.NumberFormat('fr-FR');\nconst fmtPct = (v)=> (v>0?'+':'') + v.toFixed(1).replace('.',',') + ' %';\nconst fmtCompactEUR = (v)=> v>=1e6 ? (v/1e6).toFixed(1).replace('.',',') + ' M €' : fmtEUR.format(v);\n\nconst state = { search:'', priority:'ALL', commune:'', passoireOnly:false, terrenoOnly:false,\n                periodo:'', suivi:'', tipoView:'TODOS', sortKey: IDX.score, sortDir:-1, tSortKey: TIDX.area, tSortDir:-1,\n                page:1, pageSize:40 };\n\nfunction dpeClass(d){\n  if(!d) return 'mid';\n  if(['A','B'].includes(d)) return 'good';\n  if(['E','F','G'].includes(d)) return 'bad';\n  return 'mid';\n}\n\nfunction tipoMatches(r){\n  if(state.tipoView === 'CASAS') return r[IDX.tipo] === 'Maison';\n  if(state.tipoView === 'APARTAMENTOS') return r[IDX.tipo] === 'Appartement';\n  return true;\n}\n\nfunction buildKpis(){\n  const el = document.getElementById('kpiRow');\n  let tiles;\n  if(state.tipoView === 'TERRENOS'){\n    const total = TERRENOS.length;\n    const totalArea = TERRENOS.reduce((s,r)=>s+(r[TIDX.area]||0),0);\n    const communes = new Set(TERRENOS.map(r=>r[TIDX.commune])).size;\n    const avgArea = total ? totalArea/total : 0;\n    tiles = [\n      {label:'Terrains libres identifiés', value: fmtNum.format(total), sub:'≥ 500 m² · zone U'},\n      {label:'Surface cumulée', value: fmtNum.format(Math.round(totalArea))+' m²', sub:'toutes parcelles'},\n      {label:'Surface moyenne', value: fmtNum.format(Math.round(avgArea))+' m²', sub:'par parcelle'},\n      {label:'Communes couvertes', value: fmtNum.format(communes), sub:'sur les 26 communes d\\'origine'},\n    ];\n  } else {\n    tiles = [\n      {label:'Adresses prioritaires', value: fmtNum.format(KPIS.total), sub:'score ≥ 40'},\n      {label:'Priorité maximale', value: fmtNum.format(KPIS.prioridade_a), sub:'score ≥ 70', gold:true},\n      {label:'Score moyen', value: KPIS.score_medio.toFixed(1).replace('.',','), sub:'sur 100'},\n      {label:'Passoires thermiques', value: fmtNum.format(KPIS.passoires), sub:'DPE E · F · G'},\n      {label:'Terrain ≥ 1000 m²', value: fmtNum.format(KPIS.com_terreno_grande), sub:'potentiel de division'},\n      {label:'Valeur du portefeuille', value: fmtCompactEUR(KPIS.valor_total_estimado), sub:'estimation agrégée'},\n    ];\n  }\n  el.innerHTML = tiles.map(t=>`\n    <div class=\"kpi\">\n      <div class=\"kpi-label\">${t.label}</div>\n      <div class=\"kpi-value${t.gold?' gold':''}\">${t.value}</div>\n      <div class=\"kpi-sub\">${t.sub}</div>\n    </div>`).join('');\n}\n\nfunction buildCommuneSelect(){\n  const sel = document.getElementById('communeSelect');\n  const names = [...new Set(STATS.map(s=>s[0]))].sort((a,b)=>a.localeCompare(b,'fr'));\n  names.forEach(n=>{\n    const o = document.createElement('option');\n    o.value = n; o.textContent = n;\n    sel.appendChild(o);\n  });\n}\n\nfunction buildCommunePanel(){\n  const list = document.getElementById('communeList');\n  const rows = [...STATS].sort((a,b)=> (b[4]||0) - (a[4]||0));\n  const max = Math.max(...rows.map(r=>r[4]||0));\n  list.innerHTML = rows.map(r=>{\n    const [commune,, nbVentes, prixBrut, prixActualise, evo, tauxAnnuel] = r;\n    const pct = max ? Math.round((prixActualise||0)/max*100) : 0;\n    const upFlag = (tauxAnnuel||0) >= 0;\n    return `<div class=\"commune-row\" data-commune=\"${commune}\">\n      <span class=\"commune-name\">${commune}</span>\n      <span class=\"commune-val\">${fmtNum.format(prixActualise||0)} €</span>\n      <div class=\"commune-bar-track\"><div class=\"commune-bar-fill\" style=\"width:${pct}%\"></div></div>\n      <div class=\"commune-meta\">\n        <span>${fmtNum.format(nbVentes||0)} ventes · brut ${fmtNum.format(prixBrut||0)} €</span>\n        <span class=\"evo ${upFlag?'up':'down'}\">${upFlag?'▲':'▼'} ${Math.abs(tauxAnnuel||0).toFixed(1)}%/an</span>\n      </div>\n    </div>`;\n  }).join('');\n  list.querySelectorAll('.commune-row').forEach(row=>{\n    row.addEventListener('click', ()=>{\n      const c = row.dataset.commune;\n      state.commune = (state.commune === c) ? '' : c;\n      document.getElementById('communeSelect').value = state.commune;\n      state.page = 1;\n      render();\n    });\n  });\n}\n\nfunction periodoOf(ano){\n  if(ano==null) return 'INCONNU';\n  const a = Math.round(ano);\n  if(a < 1948) return 'AVANT_1948';\n  if(a < 1975) return '1948_1974';\n  if(a < 2000) return '1975_1999';\n  if(a <= 2016) return '2000_2016';\n  return '2016_2026';\n}\n\nfunction filtered(){\n  let rows = LEADS.filter(tipoMatches);\n  if(state.priority !== 'ALL') rows = rows.filter(r=>r[IDX.prioridade]===state.priority);\n  if(state.commune) rows = rows.filter(r=>r[IDX.commune]===state.commune);\n  if(state.passoireOnly) rows = rows.filter(r=>r[IDX.passoire]===true);\n  if(state.terrenoOnly) rows = rows.filter(r=>(r[IDX.terreno]||0) >= 1000);\n  if(state.periodo) rows = rows.filter(r=>periodoOf(r[IDX.ano])===state.periodo);\n  if(state.suivi) rows = rows.filter(suiviMatches);\n  if(state.search){\n    const q = state.search.toLowerCase();\n    rows = rows.filter(r=> (r[IDX.adresse]||'').toLowerCase().includes(q) || (r[IDX.commune]||'').toLowerCase().includes(q));\n  }\n  const key = state.sortKey, dir = state.sortDir;\n  rows = [...rows].sort((a,b)=>{\n    const av = a[key], bv = b[key];\n    if(av==null && bv==null) return 0;\n    if(av==null) return 1;\n    if(bv==null) return -1;\n    if(typeof av === 'string') return dir * av.localeCompare(bv,'fr');\n    return dir * (av - bv);\n  });\n  return rows;\n}\n\nfunction filteredTerrenos(){\n  let rows = TERRENOS;\n  if(state.commune) rows = rows.filter(r=>r[TIDX.commune]===state.commune);\n  if(state.search){\n    const q = state.search.toLowerCase();\n    rows = rows.filter(r=> (r[TIDX.parcela]||'').toLowerCase().includes(q) || (r[TIDX.commune]||'').toLowerCase().includes(q));\n  }\n  const key = state.tSortKey, dir = state.tSortDir;\n  rows = [...rows].sort((a,b)=>{\n    const av = a[key], bv = b[key];\n    if(av==null && bv==null) return 0;\n    if(av==null) return 1;\n    if(bv==null) return -1;\n    if(typeof av === 'string') return dir * av.localeCompare(bv,'fr');\n    return dir * (av - bv);\n  });\n  return rows;\n}\n\nfunction rowDetail(r, idx){\n  const blocks = [];\n  if(r[IDX.argDpe]) blocks.push({h:'Argument — passoire thermique', p:r[IDX.argDpe]});\n  if(r[IDX.argTerreno]) blocks.push({h:'Argument — terrain', p:r[IDX.argTerreno]});\n  if(r[IDX.argPrudent]) blocks.push({h:'Argument — tendance de marché', p:r[IDX.argPrudent]});\n  blocks.push({h:'Motifs du score', p:r[IDX.motivos] || '—'});\n  if(r[IDX.comparaveis]) blocks.push({h:'Ventes comparables (prix réel de l\\'année)', p:r[IDX.comparaveis]});\n  const compTxt = r[IDX.nbComp] ? `${r[IDX.nbComp]} vente(s) comparable(s) dans la rue/commune` : 'Aucun comparable direct dans cette rue';\n  const srcLbl = {DPE:'DPE — surface habitable mesurée', DVF:'DVF — fichiers fonciers, souvent sous-estimée', BDNB:'BDNB — estimation : emprise au sol × niveaux × 0,8'};\n  const surfaceInfo = r[IDX.superficie]!=null ? `${Math.round(r[IDX.superficie])} m² (${srcLbl[r[IDX.sourceSurface]] || 'DVF'})` : (r[IDX.superficieDpe]!=null ? `${Math.round(r[IDX.superficieDpe])} m² (DPE)` : 'surface inconnue');\n  return `<div class=\"detail-grid\">\n    ${blocks.map(b=>`<div class=\"detail-block\"><h4>${b.h}</h4><p class=\"argument-quote\">${b.p}</p></div>`).join('')}\n    <div class=\"detail-block\"><h4>Base d'estimation</h4><p>${compTxt}. Surface : ${surfaceInfo}. Année de construction : ${r[IDX.ano]||'inconnue'}. Ancienneté de détention : ${r[IDX.duree]!=null? r[IDX.duree]+' ans' : 'jamais vendu sur la fenêtre DVF'}. Prix au m² actualisé à 2025.</p></div>\n  </div>\n  <div class=\"cta-row\">\n    ${r[IDX.gmaps] ? `<a class=\"cta\" href=\"${r[IDX.gmaps]}\" target=\"_blank\" rel=\"noopener\">Voir sur la carte ↗</a>` : ''}\n    ${r[IDX.fichaIdx]!=null ? `<a class=\"cta\" href=\"/api/ficha?n=${r[IDX.fichaIdx]}\" target=\"_blank\" rel=\"noopener\">Télécharger la fiche PDF ↓</a>` : ''}\n  </div>`;\n}\n\nfunction renderLeads(){\n  const rows = filtered();\n  const total = rows.length;\n  const pages = Math.max(1, Math.ceil(total/state.pageSize));\n  state.page = Math.min(state.page, pages);\n  const start = (state.page-1)*state.pageSize;\n  const pageRows = rows.slice(start, start+state.pageSize);\n\n  const tbody = document.getElementById('tbody');\n  if(pageRows.length === 0){\n    tbody.innerHTML = `<tr><td colspan=\"9\" class=\"empty-state\">Aucune adresse ne correspond à ces filtres.</td></tr>`;\n  } else {\n    tbody.innerHTML = pageRows.map((r,i)=>{\n      const gi = start+i;\n      const dc = dpeClass(r[IDX.dpe]);\n      const priorityCls = r[IDX.prioridade]==='A' ? 'pA' : 'pB';\n      const priorityLbl = ({A:'A · maximale', B:'B · élevée', C:'C · moyenne', D:'D · faible'})[r[IDX.prioridade]] || (r[IDX.prioridade]||'—');\n      const mv = r[IDX.maisvalia];\n      const superficie = r[IDX.superficie]!=null ? r[IDX.superficie] : r[IDX.superficieDpe];\n      const fn = r[IDX.fichaIdx];\n      const blocked = (SUIVI.get(r[IDX.adresse])||{}).statut === 'ne_plus';\n      return `<tr class=\"row\" data-idx=\"${gi}\">\n        <td class=\"sel-td\">${fn!=null && !blocked ? `<input type=\"checkbox\" class=\"sel-cb\" data-n=\"${fn}\"${SELECTION.has(fn)?' checked':''} aria-label=\"Sélectionner pour courrier\">` : ''}</td>\n        <td><span class=\"chev\">▸</span><span class=\"pill ${priorityCls}\">${priorityLbl}</span><br>\n            <span class=\"addr\">${r[IDX.adresse]||'—'}</span>${suiviPill(r)}<span class=\"addr-sub\">${r[IDX.commune]||''} · ${r[IDX.secteur]||''}</span></td>\n        <td class=\"num\">${r[IDX.score]!=null?r[IDX.score]:'—'}</td>\n        <td>${r[IDX.tipo]||'—'}</td>\n        <td class=\"num\">${superficie!=null?Math.round(superficie)+' m²':'—'}</td>\n        <td><div class=\"dpe-wrap\"><span class=\"badge-dpe ${dc}\">${r[IDX.dpe]||'?'}</span>${r[IDX.echeanceDpe]?`<span class=\"dpe-echeance\">interdit ${r[IDX.echeanceDpe]}</span>`:''}</div></td>\n        <td class=\"num\">${r[IDX.terreno]!=null?Math.round(r[IDX.terreno])+' m²':'—'}</td>\n        <td class=\"num\">${r[IDX.valor]!=null?fmtEUR.format(r[IDX.valor]):'—'}</td>\n        <td class=\"num\">${mv!=null?fmtPct(mv):'—'}</td>\n      </tr>\n      <tr class=\"detail\" data-detail-for=\"${gi}\"><td colspan=\"9\">${rowDetail(r,gi)}${suiviForm(r)}</td></tr>`;\n    }).join('');\n\n    tbody.querySelectorAll('tr.row').forEach(tr=>{\n      tr.addEventListener('click', (e)=>{\n        if(e.target.closest('a') || e.target.closest('.sel-td')) return;\n        const idx = tr.dataset.idx;\n        const det = tbody.querySelector(`tr.detail[data-detail-for=\"${idx}\"]`);\n        tr.classList.toggle('open');\n        det.classList.toggle('open');\n      });\n    });\n  }\n\n  document.getElementById('countBadge').innerHTML = `<b>${fmtNum.format(total)}</b> sur ${fmtNum.format(LEADS.length)} adresses`;\n  document.getElementById('pageLabel').textContent = `Page ${state.page} sur ${pages}`;\n  document.getElementById('prevPage').disabled = state.page<=1;\n  document.getElementById('nextPage').disabled = state.page>=pages;\n\n  document.querySelectorAll('.commune-row').forEach(row=>{\n    row.classList.toggle('active', row.dataset.commune === state.commune);\n  });\n}\n\nfunction renderTerrenos(){\n  const rows = filteredTerrenos();\n  const total = rows.length;\n  const pages = Math.max(1, Math.ceil(total/state.pageSize));\n  state.page = Math.min(state.page, pages);\n  const start = (state.page-1)*state.pageSize;\n  const pageRows = rows.slice(start, start+state.pageSize);\n\n  const tbody = document.getElementById('tbodyTerrenos');\n  if(pageRows.length === 0){\n    tbody.innerHTML = `<tr><td colspan=\"7\" class=\"empty-state\">Aucun terrain ne correspond à ces filtres.</td></tr>`;\n  } else {\n    tbody.innerHTML = pageRows.map(r=>{\n      return `<tr>\n        <td>${r[TIDX.parcela]||'—'}</td>\n        <td>${r[TIDX.commune]||'—'}</td>\n        <td class=\"num\">${r[TIDX.area]!=null?fmtNum.format(Math.round(r[TIDX.area]))+' m²':'—'}</td>\n        <td>${r[TIDX.zonaPlu]||'—'}</td>\n        <td>${r[TIDX.zonaLibelle]||'—'}</td>\n        <td>${r[TIDX.poiAlerta] ? `<span class=\"poi-alerta\">⚠ ${r[TIDX.poiAlerta]}</span>` : '—'}</td>\n        <td>${r[TIDX.linkMapa] ? `<a class=\"cta\" href=\"${r[TIDX.linkMapa]}\" target=\"_blank\" rel=\"noopener\">Voir sur la carte ↗</a>` : '—'}</td>\n      </tr>`;\n    }).join('');\n  }\n\n  document.getElementById('countBadge').innerHTML = `<b>${fmtNum.format(total)}</b> sur ${fmtNum.format(TERRENOS.length)} terrains`;\n  document.getElementById('pageLabel').textContent = `Page ${state.page} sur ${pages}`;\n  document.getElementById('prevPage').disabled = state.page<=1;\n  document.getElementById('nextPage').disabled = state.page>=pages;\n\n  document.querySelectorAll('.commune-row').forEach(row=>{\n    row.classList.toggle('active', row.dataset.commune === state.commune);\n  });\n}\n\nfunction render(){\n  if(state.tipoView === 'TERRENOS') renderTerrenos();\n  else renderLeads();\n}\n\nfunction updateModeUI(){\n  const isTerrenos = state.tipoView === 'TERRENOS';\n  document.getElementById('leadsTable').hidden = isTerrenos;\n  document.getElementById('terrenosTable').hidden = !isTerrenos;\n  document.getElementById('prioritySeg').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('passoireLabel').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('terrenoLabel').style.display = isTerrenos ? 'none' : '';\n  document.getElementById('periodoSelect').style.display = isTerrenos ? 'none' : '';\n}\n\n// -------------------------------------------------------- ROTEIRO DE PROSPECÇÃO ---\n// Regroupe les adresses de plus fort potentiel d'une commune et propose un ordre de\n// visite (plus proche voisin, à vol d'oiseau) — un point de départ pour organiser une\n// tournée, pas un calcul d'itinéraire routier réel. N'utilise que des données déjà\n// présentes dans le dashboard (lat/lon extraits du lien Google Maps déjà embarqué),\n// aucune nouvelle donnée ni service externe.\nfunction extractLatLon(gmapsUrl){\n  if(!gmapsUrl) return null;\n  const m = gmapsUrl.match(/query=(-?\\d+\\.?\\d*),(-?\\d+\\.?\\d*)/);\n  if(!m) return null;\n  return { lat: parseFloat(m[1]), lon: parseFloat(m[2]) };\n}\n\nfunction haversineKm(a, b){\n  const R = 6371;\n  const dLat = (b.lat-a.lat) * Math.PI/180;\n  const dLon = (b.lon-a.lon) * Math.PI/180;\n  const la1 = a.lat * Math.PI/180, la2 = b.lat * Math.PI/180;\n  const h = Math.sin(dLat/2)**2 + Math.cos(la1)*Math.cos(la2)*Math.sin(dLon/2)**2;\n  return 2 * R * Math.asin(Math.sqrt(h));\n}\n\n// Heurística do vizinho mais próximo: parte da morada de maior score e, a cada passo,\n// escolhe a mais próxima ainda não visitada. Não é o TSP ótimo, mas é rápido e dá uma\n// rota razoável para um punhado de paragens (5-20).\nfunction buildRoute(points){\n  if(points.length === 0) return [];\n  const remaining = [...points];\n  const route = [remaining.shift()];\n  while(remaining.length){\n    const last = route[route.length-1];\n    let bestIdx = 0, bestDist = Infinity;\n    remaining.forEach((p,i)=>{\n      const d = haversineKm(last, p);\n      if(d < bestDist){ bestDist = d; bestIdx = i; }\n    });\n    const [next] = remaining.splice(bestIdx,1);\n    next._distFromPrev = bestDist;\n    route.push(next);\n  }\n  return route;\n}\n\nfunction buildRouteCommuneSelect(){\n  const sel = document.getElementById('routeCommune');\n  const names = [...new Set(LEADS.map(r=>r[IDX.commune]).filter(Boolean))].sort((a,b)=>a.localeCompare(b,'fr'));\n  names.forEach(n=>{\n    const o = document.createElement('option');\n    o.value = n; o.textContent = n;\n    sel.appendChild(o);\n  });\n}\n\nfunction generateRoute(){\n  const commune = document.getElementById('routeCommune').value;\n  const prio = document.getElementById('routePriority').value;\n  const count = parseInt(document.getElementById('routeCount').value, 10);\n  const resultEl = document.getElementById('routeResult');\n\n  if(!commune){\n    resultEl.innerHTML = '<p class=\"route-empty\">Choisis une commune pour générer un itinéraire.</p>';\n    return;\n  }\n\n  let rows = LEADS.filter(r => r[IDX.commune] === commune);\n  if(prio === 'A') rows = rows.filter(r => r[IDX.prioridade] === 'A');\n  rows = [...rows].sort((a,b)=> (b[IDX.score]||0) - (a[IDX.score]||0)).slice(0, count);\n\n  const points = rows.map(r=>{\n    const ll = extractLatLon(r[IDX.gmaps]);\n    return ll ? { ...ll, row: r } : null;\n  }).filter(Boolean);\n\n  if(points.length === 0){\n    resultEl.innerHTML = '<p class=\"route-empty\">Aucune coordonnée disponible pour cette sélection.</p>';\n    return;\n  }\n\n  const route = buildRoute(points);\n  const listHtml = route.map((p,i)=>{\n    const r = p.row;\n    const distTxt = i===0 ? 'point de départ' : `+${p._distFromPrev.toFixed(1)} km`;\n    return `<li>\n      <span class=\"route-addr\">${r[IDX.adresse]} <span class=\"route-score\">— score ${r[IDX.score]}</span></span>\n      <span class=\"route-dist\">${distTxt}</span>\n    </li>`;\n  }).join('');\n\n  const totalKm = route.reduce((s,p)=> s + (p._distFromPrev||0), 0);\n  window.__routeRows = route.map(p=>p.row);\n  const waypoints = route.map(p=>`${p.lat},${p.lon}`);\n  const origin = waypoints[0];\n  const destination = waypoints[waypoints.length-1];\n  const middle = waypoints.slice(1,-1).join('|');\n  let mapsUrl = `https://www.google.com/maps/dir/?api=1&origin=${origin}&destination=${destination}`;\n  if(middle) mapsUrl += `&waypoints=${encodeURIComponent(middle)}`;\n\n  resultEl.innerHTML = `\n    <p style=\"margin:0 0 .6rem 0; font-size:.82rem; color:var(--ink-soft);\">\n      ${route.length} arrêts · ${totalKm.toFixed(1)} km à vol d'oiseau entre les points (distance routière réelle probablement plus longue)\n    </p>\n    <ul class=\"route-list\">${listHtml}</ul>\n    <a class=\"route-open\" href=\"${mapsUrl}\" target=\"_blank\" rel=\"noopener\">Ouvrir l'itinéraire dans Google Maps ↗</a>\n    <button type=\"button\" class=\"route-generate\" id=\"routeSelect\" style=\"margin-left:.6rem\">Préparer les courriers de cet itinéraire</button>\n  `;\n}\n\nfunction init(){\n  buildKpis();\n  buildCommuneSelect();\n  buildCommunePanel();\n  buildRouteCommuneSelect();\n  updateModeUI();\n\n  document.getElementById('searchInput').addEventListener('input', (e)=>{\n    state.search = e.target.value.trim();\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#tipoSeg button').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#tipoSeg button').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active');\n      state.tipoView = btn.dataset.val;\n      state.page = 1;\n      updateModeUI();\n      buildKpis();\n      render();\n    });\n  });\n  document.querySelectorAll('#prioritySeg button').forEach(btn=>{\n    btn.addEventListener('click', ()=>{\n      document.querySelectorAll('#prioritySeg button').forEach(b=>b.classList.remove('active'));\n      btn.classList.add('active');\n      state.priority = btn.dataset.val;\n      state.page = 1;\n      render();\n    });\n  });\n  document.getElementById('communeSelect').addEventListener('change', (e)=>{\n    state.commune = e.target.value;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('periodoSelect').addEventListener('change', (e)=>{\n    state.periodo = e.target.value;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('passoireToggle').addEventListener('change', (e)=>{\n    state.passoireOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.getElementById('terrenoToggle').addEventListener('change', (e)=>{\n    state.terrenoOnly = e.target.checked;\n    state.page = 1;\n    render();\n  });\n  document.querySelectorAll('#leadsTable thead th[data-key]').forEach(th=>{\n    th.addEventListener('click', ()=>{\n      const key = parseInt(th.dataset.key,10);\n      if(state.sortKey === key) state.sortDir *= -1;\n      else { state.sortKey = key; state.sortDir = -1; }\n      document.querySelectorAll('#leadsTable thead th').forEach(h=>h.classList.remove('sorted'));\n      th.classList.add('sorted');\n      const arrow = th.querySelector('.arrow');\n      if(arrow) arrow.textContent = state.sortDir===-1 ? '▼' : '▲';\n      render();\n    });\n  });\n  document.querySelectorAll('#terrenosTable thead th[data-tkey]').forEach(th=>{\n    th.addEventListener('click', ()=>{\n      const key = parseInt(th.dataset.tkey,10);\n      if(state.tSortKey === key) state.tSortDir *= -1;\n      else { state.tSortKey = key; state.tSortDir = -1; }\n      document.querySelectorAll('#terrenosTable thead th').forEach(h=>h.classList.remove('sorted'));\n      th.classList.add('sorted');\n      const arrow = th.querySelector('.arrow');\n      if(arrow) arrow.textContent = state.tSortDir===-1 ? '▼' : '▲';\n      render();\n    });\n  });\n  document.getElementById('prevPage').addEventListener('click', ()=>{ state.page--; render(); });\n  document.getElementById('nextPage').addEventListener('click', ()=>{ state.page++; render(); });\n\n  document.getElementById('routeToggleBtn').addEventListener('click', ()=>{\n    const panel = document.getElementById('routePanel');\n    panel.hidden = !panel.hidden;\n  });\n  document.getElementById('routeGenerateBtn').addEventListener('click', generateRoute);\n  document.getElementById('routeResult').addEventListener('click', (e)=>{\n    if(e.target.id === 'routeSelect' && window.__routeRows) selectRows(window.__routeRows);\n  });\n  initSuivi();\n\n  render();\n}\n\n/* radar-suivi v1 — seguimento das moradas e cartas em lote */\nconst SUIVI = new Map();\nlet SUIVI_OK = false, SUIVI_ERR = '';\nconst SUIVI_LBL = {courrier:'Courrier envoyé', relance:'À relancer', repondu:'A répondu', rdv:'RDV / estimation',\n  mandat:'Mandat signé', refus:'Pas intéressé', ne_plus:'Ne plus contacter'};\nconst SELECTION = new Set();\nconst SEL_MAX = 100;\nconst escHtml = (s)=> String(s==null?'':s).replace(/[&<>\"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst todayIso = ()=> new Date().toISOString().slice(0,10);\nconst isoPlus = (d)=> { const t = new Date(); t.setDate(t.getDate()+d); return t.toISOString().slice(0,10); };\n\nasync function loadSuivi(){\n  try{\n    const r = await fetch('/api/suivi', {cache:'no-store'});\n    const j = await r.json();\n    if(!r.ok) throw new Error(j.error || ('HTTP '+r.status));\n    SUIVI.clear();\n    (j.rows||[]).forEach(x=>SUIVI.set(x.adresse, x));\n    SUIVI_OK = true; SUIVI_ERR = '';\n  }catch(e){ SUIVI_OK = false; SUIVI_ERR = e.message; }\n  renderSuiviWarn();\n}\n\nfunction renderSuiviWarn(){\n  let el = document.getElementById('suiviWarn');\n  if(!el){\n    el = document.createElement('div'); el.id = 'suiviWarn'; el.className = 'suivi-warn';\n    const card = document.querySelector('.table-card'); card.parentNode.insertBefore(el, card);\n  }\n  el.hidden = SUIVI_OK;\n  el.textContent = 'Suivi des contacts indisponible : ' + SUIVI_ERR;\n}\n\nfunction suiviMatches(r){\n  const f = state.suivi; if(!f) return true;\n  const s = SUIVI.get(r[IDX.adresse]);\n  if(f === 'NONE') return !s || !s.statut;\n  if(f === 'ARELANCER') return !!(s && s.relance_le && s.relance_le <= isoPlus(7) && !['mandat','refus','ne_plus'].includes(s.statut));\n  return !!(s && s.statut === f);\n}\n\nfunction suiviPill(r){\n  const s = SUIVI.get(r[IDX.adresse]);\n  if(!s || (!s.statut && !s.relance_le)) return '';\n  const late = s.relance_le && s.relance_le <= todayIso() && !['mandat','refus','ne_plus'].includes(s.statut);\n  const lbl = s.statut ? SUIVI_LBL[s.statut] : 'Relance';\n  const rel = s.relance_le ? ' · ' + s.relance_le.split('-').reverse().join('/') : '';\n  return `<span class=\"suivi-pill s-${s.statut||'relance'}${late?' late':''}\">${escHtml(lbl+rel)}</span>`;\n}\n\nfunction suiviForm(r){\n  const n = r[IDX.fichaIdx];\n  if(n == null) return '';\n  const s = SUIVI.get(r[IDX.adresse]) || {};\n  const opts = ['<option value=\"\">Non contactée</option>'].concat(Object.entries(SUIVI_LBL).map(([k,v])=>\n    `<option value=\"${k}\"${s.statut===k?' selected':''}>${v}</option>`)).join('');\n  const maj = s.updated_at ? 'Mis à jour le ' + new Date(s.updated_at).toLocaleDateString('fr-FR') : '';\n  const courrier = s.courrier_le ? ' · dernier courrier le ' + s.courrier_le.split('-').reverse().join('/') : '';\n  return `<div class=\"suivi-box\" data-suivi-for=\"${n}\">\n    <h4>Suivi du contact</h4>\n    ${SUIVI_OK ? '' : `<p class=\"suivi-msg\">Indisponible : ${escHtml(SUIVI_ERR)}</p>`}\n    <div class=\"suivi-grid\">\n      <label>Statut<select data-f=\"statut\">${opts}</select></label>\n      <label>À relancer le<input type=\"date\" data-f=\"relance_le\" value=\"${escHtml(s.relance_le||'')}\"></label>\n    </div>\n    <textarea data-f=\"note\" placeholder=\"Note (échange, attentes, projet…)\">${escHtml(s.note||'')}</textarea>\n    <div class=\"suivi-actions\">\n      <button type=\"button\" data-act=\"save\">Enregistrer</button>\n      <button type=\"button\" data-act=\"lettre\" style=\"background:#AD8A45;color:#101820\">Texte du courrier</button>\n      <span class=\"suivi-msg\" data-f=\"msg\">${escHtml(maj + courrier)}</span>\n    </div>\n  </div>`;\n}\n\nasync function saveSuivi(box, r){\n  const msg = box.querySelector('[data-f=\"msg\"]');\n  const body = { adresse: r[IDX.adresse], statut: box.querySelector('[data-f=\"statut\"]').value || null,\n    relance_le: box.querySelector('[data-f=\"relance_le\"]').value || null, note: box.querySelector('[data-f=\"note\"]').value || null };\n  msg.textContent = 'Enregistrement…';\n  try{\n    const res = await fetch('/api/suivi', {method:'POST', headers:{'Content-Type':'application/json'}, body: JSON.stringify(body)});\n    const j = await res.json();\n    if(!res.ok) throw new Error(j.error || ('HTTP '+res.status));\n    SUIVI.set(j.adresse || body.adresse, Object.assign({}, SUIVI.get(body.adresse)||{}, j));\n    msg.textContent = 'Enregistré ✓';\n    const tr = box.closest('tr.detail'); const idx = tr && tr.dataset.detailFor;\n    const row = idx!=null && document.querySelector(`tr.row[data-idx=\"${idx}\"] .addr-sub`);\n    if(row){ const old = row.parentNode.querySelector('.suivi-pill'); if(old) old.remove(); row.insertAdjacentHTML('beforebegin', suiviPill(r)); }\n  }catch(e){ msg.textContent = 'Erreur : ' + e.message; }\n}\n\nfunction renderSelBar(){\n  let bar = document.getElementById('selBar');\n  if(!bar){\n    bar = document.createElement('div'); bar.id = 'selBar'; bar.className = 'sel-bar';\n    bar.innerHTML = `<span id=\"selCount\"></span>\n      <button type=\"button\" class=\"primary\" id=\"selLetters\">Textes des courriers (à copier)</button>\n      <button type=\"button\" id=\"selFiches\">Fiches d'estimation (PDF)</button>\n      <button type=\"button\" id=\"selClear\">Vider la sélection</button>`;\n    document.body.appendChild(bar);\n    document.getElementById('selClear').addEventListener('click', ()=>{ SELECTION.clear(); renderSelBar(); render(); });\n    document.getElementById('selLetters').addEventListener('click', ()=>generateLetters([...SELECTION], true));\n    document.getElementById('selFiches').addEventListener('click', generateFiches);\n  }\n  bar.hidden = SELECTION.size === 0;\n  document.getElementById('selCount').textContent = `${SELECTION.size} adresse(s) sélectionnée(s)` + (SELECTION.size > SEL_MAX ? ` — maximum ${SEL_MAX}` : '');\n  document.getElementById('selLetters').disabled = SELECTION.size > SEL_MAX;\n  document.getElementById('selFiches').disabled = SELECTION.size > SEL_MAX;\n}\n\nfunction toggleSel(n, on){\n  n = parseInt(n,10); if(!Number.isInteger(n)) return;\n  if(on) SELECTION.add(n); else SELECTION.delete(n);\n  renderSelBar();\n}\n\nasync function postLettres(ns, format, marquer){\n  const res = await fetch('/api/lettres', {method:'POST', headers:{'Content-Type':'application/json'},\n    body: JSON.stringify({n: ns, format, marquer})});\n  if(!res.ok){ let m = 'HTTP '+res.status; try{ m = (await res.json()).error || m; }catch(_){} throw new Error(m); }\n  return res;\n}\n\n// Texto das cartas, para copiar e colar no papel timbrado da agencia.\nasync function generateLetters(ns, marquer){\n  if(!ns.length) return;\n  const btn = document.getElementById('selLetters'); const old = btn.textContent;\n  btn.disabled = true; btn.textContent = 'Préparation…';\n  try{\n    const j = await (await postLettres(ns, 'texte', marquer)).json();\n    showLetters(j.lettres || [], marquer);\n    if(marquer){ SELECTION.clear(); await loadSuivi(); renderSelBar(); render(); }\n    if(j.retirees) alertMsg(`${j.retirees} adresse(s) « Ne plus contacter » retirée(s).`);\n  }catch(e){ alertMsg('Courriers non générés : ' + e.message); }\n  finally{ btn.textContent = old; btn.disabled = SELECTION.size > SEL_MAX; }\n}\n\nasync function copyText(t, btn){\n  try{ await navigator.clipboard.writeText(t); }\n  catch(_){ const ta = document.createElement('textarea'); ta.value = t; document.body.appendChild(ta); ta.select(); document.execCommand('copy'); ta.remove(); }\n  if(btn){ const o = btn.textContent; btn.textContent = 'Copié ✓'; setTimeout(()=>btn.textContent = o, 1500); }\n}\n\nfunction showLetters(lettres, marquees){\n  const old = document.getElementById('ltModal'); if(old) old.remove();\n  const m = document.createElement('div'); m.id = 'ltModal'; m.className = 'lt-modal';\n  m.innerHTML = `<div class=\"lt-panel\" role=\"dialog\" aria-label=\"Textes des courriers\">\n    <div class=\"lt-head\"><h3>${lettres.length} courrier(s) à coller sur votre papier à en-tête</h3>\n      <div style=\"display:flex;gap:.5rem;flex-wrap:wrap\">\n        ${lettres.length>1 ? '<button type=\"button\" class=\"primary\" data-lt=\"all\">Tout copier</button>' : ''}\n        <button type=\"button\" data-lt=\"close\">Fermer</button></div></div>\n    <p class=\"lt-hint\">Copiez chaque texte et collez-le dans le modèle Word de l'agence (en-tête et coordonnées déjà imprimés).\n      La fiche d'estimation de chaque adresse se joint avec « Fiches d'estimation (PDF) ».${marquees ? ' Ces adresses sont marquées « Courrier envoyé ».' : ''}</p>\n    ${lettres.map((l,i)=>`<div class=\"lt-item\"><h4><span>${i+1}. ${escHtml(l.adresse)}</span>\n      <button type=\"button\" data-lt=\"one\" data-i=\"${i}\">Copier</button></h4>\n      <textarea readonly>${escHtml(l.texte)}</textarea></div>`).join('')}\n  </div>`;\n  document.body.appendChild(m);\n  m.addEventListener('click', (e)=>{\n    const b = e.target.closest('[data-lt]');\n    if(e.target === m || (b && b.dataset.lt === 'close')) return m.remove();\n    if(!b) return;\n    if(b.dataset.lt === 'one') copyText(lettres[parseInt(b.dataset.i,10)].texte, b);\n    if(b.dataset.lt === 'all') copyText(lettres.map(l=>l.texte).join(String.fromCharCode(10,10,12,10)), b);\n  });\n}\n\n// Fichas de estimativa (PDF) das moradas selecionadas, a juntar as cartas.\nasync function generateFiches(){\n  const ns = [...SELECTION]; if(!ns.length) return;\n  const btn = document.getElementById('selFiches'); const old = btn.textContent;\n  btn.disabled = true; btn.textContent = 'Préparation…';\n  const win = window.open('', '_blank');\n  try{\n    const blob = await (await postLettres(ns, 'fiches', false)).blob();\n    const url = URL.createObjectURL(blob);\n    if(win) win.location = url; else { const a = document.createElement('a'); a.href = url; a.download = 'fiches.pdf'; a.click(); }\n  }catch(e){ if(win) win.close(); alertMsg('Fiches non générées : ' + e.message); }\n  finally{ btn.textContent = old; btn.disabled = SELECTION.size > SEL_MAX; }\n}\n\nfunction alertMsg(t){\n  const el = document.getElementById('suiviWarn'); if(!el) return;\n  el.hidden = false; el.textContent = t;\n  setTimeout(()=>{ renderSuiviWarn(); }, 8000);\n}\n\nfunction selectRows(rows){\n  rows.forEach(r=>{ if(r[IDX.fichaIdx]!=null && (SUIVI.get(r[IDX.adresse])||{}).statut !== 'ne_plus') SELECTION.add(r[IDX.fichaIdx]); });\n  renderSelBar(); render();\n}\n\nfunction initSuivi(){\n  const sel = document.getElementById('suiviSelect');\n  if(sel) sel.addEventListener('change', (e)=>{ state.suivi = e.target.value; state.page = 1; render(); });\n  const tbody = document.getElementById('tbody');\n  tbody.addEventListener('change', (e)=>{\n    const cb = e.target.closest('.sel-cb'); if(cb) toggleSel(cb.dataset.n, cb.checked);\n  });\n  tbody.addEventListener('click', (e)=>{\n    if(e.target.closest('.sel-td')) return;\n    const btn = e.target.closest('[data-act]'); if(!btn) return;\n    const box = btn.closest('.suivi-box'); const n = parseInt(box.dataset.suiviFor,10);\n    if(btn.dataset.act === 'lettre') return generateLetters([n], false);\n    const r = LEADS.find(x=>x[IDX.fichaIdx]===n); if(r) saveSuivi(box, r);\n  }, true);\n  const selPage = document.getElementById('selPage');\n  if(selPage) selPage.addEventListener('change', (e)=>{\n    const rows = filtered(); const start = (state.page-1)*state.pageSize;\n    rows.slice(start, start+state.pageSize).forEach(r=>{ const n = r[IDX.fichaIdx]; if(n==null) return;\n      if(e.target.checked && (SUIVI.get(r[IDX.adresse])||{}).statut !== 'ne_plus') SELECTION.add(n); else SELECTION.delete(n); });\n    renderSelBar(); render();\n  });\n  renderSelBar();\n  loadSuivi().then(()=>render());\n}\n\ninit();\n\n</script>\n\n\n\n</body></html>";
